     (block 
          (sett Bonus 0)
          (sett Bonus (add Bonus
                           (divide (WAGetTurn) 10)
                      )
          )
          (sett HPDiff (subtract (WAGetMaxHitPoints #target)
                              (WAGetMaxHitPoints #superstar)
                       )
          )
          (sett Bonus (add Bonus (divide HPDiff 10)))
          (sett ConnList '())
          (enum (WAGetConnectedMoves #superstar) ConnMove
                (block 
                     (sett IsDup 0)
                     (sett Index (count ConnList))
                     (loop (greater Index 0)
                           (block 
                                (if ((eq (WAGetName ConnMove)
                                         (WAGetName (item ConnList Index))
                                     )
                                     (sett IsDup 1)
                                    )
                                )
                                (sett Index (subtract Index 1))
                           )
                     )
                     (if ((eq IsDup 0)
                          (sett ConnList (cons ConnList ConnMove))
                         )
                     )
                )
          )
          (sett Bonus (add Bonus
                           (divide (count ConnList) 2)
                      )
          )
          (sett Bonus (add Bonus
                           (subtract (WARandom 0 7) 3)
                      )
          )
          (if ((WAPlayedFanFavorite #superstar)
               (sett Bonus (subtract Bonus 1))
              )
          )
          (if ((WAPlayedRulebreaker #superstar)
               (sett Bonus (subtract Bonus 1))
              )
          )
          (if ((and (not (WAPlayedFanFavorite #superstar))
                    (not (WAPlayedRulebreaker #superstar))
               )
               (sett Bonus (add Bonus 12))
              )
          )
          (if ((greater (WAGetSubmissionDamage #target Arm) 0)
               (sett Bonus (add Bonus 1))
              )
          )
          (if ((greater (WAGetSubmissionDamage #target Back) 0)
               (sett Bonus (add Bonus 1))
              )
          )
          (if ((greater (WAGetSubmissionDamage #target Head) 0)
               (sett Bonus (add Bonus 1))
              )
          )
          (if ((greater (WAGetSubmissionDamage #target Leg) 0)
               (sett Bonus (add Bonus 1))
              )
          )
          (sett Bonus (subtract Bonus (WAGetValue #superstar Warnings)))
          (sett Bonus (subtract Bonus (WAGetValue #superstar Strength_Momentum)))
          (sett TwoLetters (WASubstring (WAGetName (WAGetOwner #this)) 0 1))
          (if ((or (eq TwoLetters "GA")
                   (eq TwoLetters "DR")
               )
               (sett Bonus (add Bonus 7))
              )
          )
          (if ((lesser Bonus 0)
               (sett Bonus 0)
              )
          )
          (if ((greater Bonus 20)
               (sett Bonus 20)
              )
          )
          (WASetValue #this Damage_Bonus (add Bonus (WAGetValue #this Damage_Bonus)))
     )
    )
