     (sett HitPoints (WAGetHitPoints (WAGetPlayedOn #this)))
     (if ((eq HitPoints 0)
          (WAMessage (WAGetOwner #this) "Lawler:" (WAGetName (WAGetPlayedOn #this)) "has" HitPoints "hit point left!")
         )
         (True
          (WAMessage (WAGetOwner #this) "Lawler:" (WAGetName (WAGetPlayedOn #this)) "has" HitPoints "hit points left!")
         )
     )
     True
)

originalScripts.Page_Played:
(if ((eq #page #this)
     (block 
          (sett PageDrawn (WADrawPage #initiator))
          (if ((eq PageDrawn 0)
               (WAMessage (WAGetOwner #initiator) "Lawler: You are out of pages in your playbook!")
              )
              (True
               (WAMessage (WAGetOwner #initiator) "Lawler: You drew" (cat (WAGetName PageDrawn) "."))
              )
          )
          True
     )
    )
    (True True)
)

originalScripts.Move_Connected:
(if ((and (eq (WAGetPlayedBy #move) #this)
          (WAHasModifier #move Impact)
     )
     (WAAddValue #this ImpactMoves (add (WAGetValue #this ImpactMoves) 1))
    )
    (True True)
)

originalScripts.Get_Page_List:
(WAEnumPlaybook 
     (WAGetActiveSuperstar (WAGetOwner #this))
     Page
     '(if ((and (WAHasValue Page "Move_Type" "hit or miss")
               (WAIsMove Page)
          )
          (WAAddToPageList #this (WAGetUNID Page) 0)
         )
     )
)

originalScripts.Special_Special:
(if ((eq #test 1)
     (if ((and (not (WAInHand (WABelongsTo #this) #this))
               (eq (WAHasControl) #User)
               (not (WAIsStunned (WAGetActiveSuperstar #User)))
               (not (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                        1
                    )
               )
          )
          True
         )
         (True Nil)
     )
    )
    (True
     (block 
          (WAOutOfPlay #this)
          True
     )
    )
)

originalScripts.Damage_Bonus:
(if ((and (eq (WAStringGetValue #move Method) "Strike")
          (eq (WAGetOwner #move)
              (WAGetOwner #this)
          )
     )
     (block 
          (sett Bonus (WARandom 1 4))
          (if ((greater Bonus (WAGetValue #move Damage))
               (sett Bonus (WAGetValue #move Damage))
              )
          )
          (WASetValue #move Damage_Bonus (add (WAGetValue #move Damage_Bonus) Bonus))
     )
    )
)

originalScripts.Special_Special:
(if ((eq #test 1)
     (block 
          (if ((or (eq (WAGetValue #this Used_Special) 2)
                   (WAIsStunned #this)
                   (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                       1
                   )
               )
               Nil
              )
              (True True)
          )
     )
    )
    ((eq #needstarget 1)
     (WAAddValue #this Target_Type 4)
    )
    (True
     (block 
          (sett BodyPart (WAStringGetValue #this User_Data))
          (WAMessage -1 "Lawler: It looks like Benoit is really going after the" BodyPart "there!")
          (if ((eq (WAGetValue #this Used_Special) 0)
               (WAAddValue #this Used_Special 1)
              )
              (True
               (WASetValue #this Used_Special (add (WAGetValue #this Used_Special) 1))
              )
          )
     )
    )
)

originalScripts.Move_Connected:
(if ((and (eq (WAGetOwner #move)
              (WAGetOwner #this)
          )
          (WAHasModifier #move 'Impact)
          (or (eq (WAGetValue #this Used_Special) 1)
              (eq (WAGetValue #this Used_Special) 2)
          )
     )
     (block 
          (sett RandomDamage (WARandom 1 4))
          (sett BodyPart (WAStringGetValue #this User_Data))
          (sett ARandom (WARandom 1 3))
          (if ((eq ARandom 1)
               (WAMessage -1 "Jim Ross: It looks like Benoit is going after the" BodyPart "with a vengeance!")
              )
              ((eq ARandom 2)
               (block 
                    (if ((WAHasModifier #target '$Female)
                         (sett Pronoun "her")
                        )
                        ((WAHasModifier #target '$Neuter)
                         (sett Pronoun "its")
                        )
                        (True
                         (sett Pronoun "his")
                        )
                    )
                    (WAMessage -1 "Jim Ross: Benoit is trying to destroy" Pronoun (cat BodyPart "!!"))
               )
              )
              ((eq ARandom 3)
               (WAMessage -1 "Lawler: The Rabid Wolverine looks like he wants to take that" BodyPart "home with him!")
              )
          )
          (WADamage #target RandomDamage BodyPart)
          True
     )
    )
    (True True)
)

originalScripts.Page_Played:
