)

originalScripts.Special_Special:
(if ((eq #test 1)
     (and (eq #User (WAGetOwner #this))
          (WAInPlay #this)
          (not (WAIsStunned (WAGetActiveSuperstar #User)))
          (not (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                   1
               )
          )
          (eq (WAGetValue #this ReadyToUse) 1)
     )
    )
    (True
     (block 
          (sett Me (WAGetActiveSuperstar #User))
          (if ((WAHasModifier Me '$Female)
               (block 
                    (sett Pron1 "her")
                    (sett Pron2 "she")
               )
              )
              ((WAHasModifier Me '$Neuter)
               (block 
                    (sett Pron1 "its")
                    (sett Pron2 "it")
               )
              )
              (True
               (block 
                    (sett Pron1 "his")
                    (sett Pron2 "he")
               )
              )
          )
          (if ((eq (WARandom 1 3) 1)
               (sett RandCmt "What agility!")
              )
              ((eq (WARandom 1 2) 1)
               (sett RandCmt "Amazing!")
              )
              (True
               (sett RandCmt (cat (cat "What will " Pron2) " do next?"))
              )
          )
          (sett CounteredName (WAGetName (WAGetValue #this $CounteredMove)))
          (sett FirstLetter (WASubstring CounteredName 0 1))
          (if ((or (eq FirstLetter "a")
                   (eq FirstLetter "e")
                   (eq FirstLetter "i")
                   (eq FirstLetter "o")
                   (eq FirstLetter "u")
               )
               (sett AAN "an")
              )
              (True
               (sett AAN "a")
              )
          )
          (WAMessage -1 "Jim Ross:" (WAGetName (WAGetOpponent Me)) "was trying for" AAN CounteredName "but" (WAGetName Me) "just landed on" Pron1 "feet!" RandCmt)
          (WAOutOfPlay #this)
          (WAAutoCounter Me)
          True
     )
    )
)

originalScripts.Move_Connected:
(if ((eq #move #this)
     (block 
          (WASetOnMat #target 1)
          (sett MoveType (WAStringGetValue #this User_data))
          (if ((eq MoveType "defensive")
               (WAMessage -1 "Jim Ross: A defensive move type is not allowed for this page to bury")
              )
              (True
               (block 
                    (sett ValidTypes '())
                    (sett Index 0)
                    (enum (WAGetHand #target) IsOfType
                          (block 
                               (if ((WAHasValue IsOfType "Move_Type" MoveType)
                                    (sett ValidTypes (cons ValidTypes Index))
                                   )
                               )
                               (sett Index (add Index 1))
                          )
                    )
                    (if ((greater (count ValidTypes) 0)
                         (block 
                              (sett HandIndex (item ValidTypes
                                                    (WARandom 1 (count ValidTypes))
                                              )
                              )
                              (sett PageTaken (WAMovePageFromHandToPlaybook #target HandIndex -1))
                              (WAMessage -1 (WAGetName #superstar) "has buried" (cat (WAGetNAme #target) "'s") (WAGetName PageTaken))
                         )
                        )
                    )
               )
              )
          )
     )
    )
)

(if ((eq #move #this)
     (block 
          (if ((eq (WAGetValue #this UsedAsCounter) 1)
               (block 
                    (sett Done (eq (WAGetHandCount #target) 0))
                    (sett NumDitched 0)
                    (sett StopNum 1)
                    (loop (not Done)
                          (block 
                               (sett Ditch (WARandom 1 (WAGetHandCount #target)))
                               (sett Card (item (WAGetHand #target) Ditch))
                               (WAMessage (WAGetOwner #target) (WAGetName #this) "has forced you to ditch" (WAGetName Card))
                               (WADitchPage #target (subtract Ditch 1))
                               (sett NumDitched (add NumDitched 1))
                               (if ((eq NumDitched StopNum)
                                    (sett Done True)
                                   )
                                   (True
                                    (sett Done (eq (WAGetHandCount #target) 0))
                                   )
                               )
                          )
                    )
               )
              )
          )
          (WASetOnMat #target 1)
          (if ((eq (WAGetValue (WAGameMap) RefDistracted)
                   1
               )
               (block 
                    (WAMessage -1 "Jim Ross: The referee is out of position -- he doesn't see the pin!")
                    True
               )
              )
              (True
               (block 
                    (WAPinSuperstar #superstar #target 1)
                    True
               )
              )
          )
          True
     )
    )
    (True True)
)

originalScripts.AI_UseSpecial:
(block 
     (sett CanPlay 0)
     (enum (WAGetHand #this) Page
           (if ((WAIsMove Page)
                (if ((WACanPlayPage #this 0 Page) 
                     (sett CanPlay (add CanPlay 1))
                    )
                )
               )
           )
     )
     (if ((eq CanPlay 0)
          (WASetValue #this AIScore (WARandom 10 50))
         )
     )
)

originalScripts.Page_Played:
(if ((eq #page #this)
     (if ((not (eq (WAGetOpponent #initiator) 0))
          (block 
               (WADrawPage (WAGetOpponent #initiator))
               (sett Heal 3)
               (sett Strength (WAGetValue #initiator Strength_Momentum))
               (if ((greater Strength 10)
                    (sett Strength 10)
                   )
               )
               (sett Heal (add Heal Strength))
               (sett DidHeal (WAHeal #initiator Heal) )
               (WAMessage (WAGetOwner #initiator) "Healed" DidHeal "points of damage on" (WAGetName #initiator))
               True
          )
         )
         (True Nil)
     )
    )
    (True True)
)

originalScripts.Special_Special:
(if ((eq #test 1)
     (and (not (WAIsStunned #this))
          (greater (WAGetValue #this Generic_Momentum) 0)
          (not (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                   1
               )
          )
          (lesser (WAGetValue #this UsedSpecial) 11)
     )
    )
    (True
     (block 
          (sett RandCmt (WARandom 1 5))
          (if ((eq RandCmt 1)
               (WAMessage -1 "Jim Ross: The Undertaker is looking to drag this match out a bit, looking to punish his opponent.")
              )
              ((eq RandCmt 2)
               (WAMessage -1 "Lawler: The Red Devil looks barely phased, JR!")
              )
              ((eq RandCmt 3)
               (WAMessage -1 "Jim Ross: Undertaker has seen it all in this business.")
              )
              ((eq RandCmt 4)
               (block 
                    (sett Opp (WAGetOpponent #this))
                    (if ((WAHasModifier Opp '$Female)
                         (sett Pronoun "her!")
                        )
                        ((WAHasModifier Opp '$Neuter)
                         (sett Pronoun "it!")
                        )
                        (True
                         (sett Pronoun "him!")
                        )
                    )
                    (WAMessage -1 "Lawler:" (WAGetName Opp) "will either give Taker respect, or he will beat it out of" Pronoun)
               )
              )
              ((eq RandCmt 5)
               (block 
                    (WAMessage -1 "Jim Ross: Taker has this almost-unreal ability to take his opponent's best shot, and still come back to win the match.")
                    (WAMessage -1 "Lawler: Well, he is 'the Dead Man'!")
               )
              )
          )
          (WASetValue #this UsedSpecial (add 1 (WAGetValue #this UsedSpecial)))
          (WASetValue #this Generic_Momentum (subtract (WAGetValue #this Generic_Momentum) 1))
          (WASetValue 
               (WAGetOpponent #this)
               Generic_Momentum
               (subtract (WAGetValue (WAGetOpponent #this) Generic_Momentum)
                      1
               )
          )
          (WASetTurnLimit (add 1 (WAGetTurnLimit)))
     )
    )
)

originalScripts.Page_Played:
(if ((eq #page #this)
     (block 
          (sett ConnLE 0)
          (enum (WAGetConnectedMoves #initiator) IsLE
                (if ((WAHasValue IsLE "Move_Type" "leg extended")
                     (sett ConnLE 1)
                    )
                )
          )
          (if ((eq ConnLE 0)
               (block 
                    (WASetValue #this PoweredUp 1)
                    (WASetValue (WAGameMap) NoSpecialAbilities 1)
               )
              )
          )
     )
    )
)

originalScripts.Get_Page_List:
(WAEnumPlaybook 
     (WAGetActiveSuperstar (WAGetOwner #this))
     Page
     '(if ((or (WAHasValue Page "Move_Type" "victim below")
              (eq (WAGetName Page) "Stone Cold Stunner")
          )
          (WAAddToPageList #this (WAGetUNID Page) 0)
         )
     )
)

originalScripts.Move_Connected:
(if ((and (eq #target #this)
          (or (and (eq (WAStringGetValue #move Method) "Agility")
                   (eq (WAGetValue #this MethodBonus) 1)
              )
              (and (eq (WAStringGetValue #move Method) "Strength")
                   (eq (WAGetValue #this MethodBonus) 2)
              )
              (and (eq (WAStringGetValue #move Method) "Strike")
                   (eq (WAGetValue #this MethodBonus) 3)
              )
              (and (eq (WAStringGetValue #move Method) "Technical")
                   (eq (WAGetValue #this MethodBonus) 4)
              )
          )
          (greater-eq (WAGetValue #move Momentum_Cost) 6)
     )
     (block 
          (sett CreatedPage (WACreatePageByUNID #this 227))
          (WAPutIntoHand #this CreatedPage)
          (if ((and (lesser-eq (WAGetValue #move Momentum_Cost) 12)
                    (WAHasModifier #move 'Impact)
                    (not (WAHasModifier #move '$NOC))
                    (not (WAHasModifier #superstar '$Female))
                    (not (WAHasModifier #superstar '$Neuter))
               )
               (if ((eq (WARandom 1 3) 1)
                    (WAMessage -1 "Jim Ross: He did it! I can't believe it! Poor Trish Stratus!!")
                   )
                   ((eq (WARandom 1 2) 1)
                    (WAMessage -1 "Lawler: That was just a bit too much, JR...")
                   )
                   (True
                    (block 
                         (WAMessage -1 "Jim Ross: I can't believe that" (WAGetName #superstar) "would hit a woman like that!")
                         (WAMessage -1 "Lawler: But those are the rules of the match, JR!")
                         (WAMessage -1 "Jim Ross: But it still isn't right.")
                    )
                   )
               )
              )
              ((and (greater-eq (WAGetValue #move Momentum_Cost) 13)
                    (WAHasModifier #move 'Impact)
                    (not (WAHasModifier #move '$NOC))
                    (not (WAHasModifier #superstar '$Female))
                    (not (WAHasModifier #superstar '$Neuter))
               )
               (if ((eq (WARandom 1 2) 1)
                    (WAMessage -1 "Jim Ross: BY GOD, I can't believe he hit Trish Stratus like that!")
                   )
                   (True
                    (WAMessage -1 "Jim Ross: In my 25 years in this business, I have never seen a more heinous act.")
                   )
               )
              )
          )
     )
    )
)

(if ((WAInPlay #this)
     (block 
          (sett DummyPage (WACreatePageByUNID #superstar (WAStringGetValue #this User_Data)))
          (sett PageUNID (WAGetUNID DummyPage))
          (sett Shuffled 0)
          (enum (WAGetInPlay #target) ToShuffle
                (if ((and (eq (WAGetUNID ToShuffle) PageUNID)
                          (eq Shuffled 0)
                     )
                     (block 
                          (sett Shuffled 1)
                          (WAOutOfPlay ToShuffle)
                          (WAPutPageInPlaybook #target PageUNID -2) 
                     )
                    )
                )
          )
     )
    )
)

originalScripts.Special_Special:
(if ((eq #test 1)
     (block 
          (if ((or (eq (WAGetValue #this Used_Special) 1)
                   (WAIsStunned #this)
                   (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                       1
                   )
               )
               Nil
              )
              (True True)
          )
     )
    )
    ((eq #needstarget 1)
     (WAAddValue #this Target_Type 3)
    )
    (True
     (block 
          (sett NewPage (WACreatePageByUNID #this #target))
          (if ((not (eq NewPage 0))
               (WAForcePage #this (WAGetOpponent #this) NewPage)
              )
          )
          (WAMessage -1 "Jim Ross: Regal always seems to get the referee to look where he wants.")
          (if ((eq (WAGetValue #this Used_Special) 0)
               (WAAddValue #this Used_Special 1)
              )
              (True
               (WASetValue #this Used_Special (add (WAGetValue #this Used_Special) 1))
              )
          )
     )
    )
)

