originalScripts.AI_PinTarget:
(if ((not (eq (WAGetLocation #this)
              (WAGetLocation #target)
          )
     )
     Nil
    )
    ((lesser (WAGetValue #this Generic_Momentum) (WAGetPinAttempts #this))
     Nil
    )
    ((greater #score (add 35
                 (multiply (WAGetPinAttempts #this) 10)
            )
     )
     True
    )
    ((greater #score 75)
     True
    )
    ((eq (WAGetTurn)
         (WAGetTurnLimit)
     )
     True
    )
    (True Nil)
)

(if ((not (eq (WAGetLocation #this)
              (WAGetLocation #target)
          )
     )
     Nil
    )
    ((lesser (WAGetValue #this Generic_Momentum) (WAGetPinAttempts #this))
     Nil
    )
    ((greater #score (add 35
                 (multiply (WAGetPinAttempts #this) 10)
            )
     )
     True
    )
    ((greater #score 75)
     True
    )
    ((eq (WAGetTurn)
         (WAGetTurnLimit)
     )
     True
    )
    (True Nil)
)

originalScripts.Page_Played:
(if ((and (not (eq #initiator #this))
          (WAHasModifier #page 'Status)
     )
     (if ((eq (WAGetName #page) "Grounded")
          (WASetValue #this GroundedOpponent 1)
         )
         ((eq (WAGetName #page) "Busted Wide Open")
          (WASetValue #this BustedWideOpenOpponent 1)
         )
         ((eq (WAGetName #page) "Frustrated")
          (WASetValue #this FrustratedOpponent 1)
         )
         ((eq (WAGetName #page) "Staggered")
          (WASetValue #this StaggeredOpponent 1)
         )
     )
    )
    ((and (eq #initiator #this)
          (WAIsMomentum #page)
     )
     (WASetValue #this PlayedMomentum (add 1 (WAGetValue #this PlayedMomentum)))
    )
)

(if ((and (eq (WAGetName #page) "Strength")
          (eq #initiator #this)
          (lesser (WAGetValue #this UsedStrengthSpecial) 2)
     )
     (block 
          (WASetValue #this UsedStrengthSpecial (add 1 (WAGetValue #this UsedStrengthSpecial)))
          (sett DrawList '())
          (WAEnumPlaybook 
               #this
               Page
               '(if ((and (WAIsSpecial Page)
                         (WAHasModifier Page 'Damage)
                    )
                    (sett DrawList (cons DrawList (WAGetUNID Page)))
                   )
               )
          )
          (if ((greater (count DrawList) 0)
               (block 
                    (sett ToDraw (item DrawList
                                       (WARandom 1 (count DrawList))
                                 )
                    )
                    (sett Drawn (WADrawPageByUNID #this ToDraw))
                    (WAMessage (WAGetOwner #this) "Drew" (WAGetName Drawn))
               )
              )
              (True
               (WAMessage (WAGetOwner #this) "Jim Ross: You have no Damage specials left in your playbook!")
              )
          )
     )
    )
    ((and (eq (WAGetName #page) "Strike")
          (eq #initiator #this)
          (lesser (WAGetValue #this UsedStrikeSpecial) 2)
     )
     (block 
          (WASetValue #this UsedStrikeSpecial (add 1 (WAGetValue #this UsedStrikeSpecial)))
          (sett DrawList '())
          (WAEnumPlaybook 
               #this
               Page
               '(if ((WAHasModifier Page 'Heel)
                    (sett DrawList (cons DrawList (WAGetUNID Page)))
                   )
               )
          )
          (if ((greater (count DrawList) 0)
               (block 
                    (sett ToDraw (item DrawList
                                       (WARandom 1 (count DrawList))
                                 )
                    )
                    (sett Drawn (WADrawPageByUNID #this ToDraw))
                    (WAMessage (WAGetOwner #this) "Drew" (WAGetName Drawn))
               )
              )
              (True
               (WAMessage (WAGetOwner #this) "Jim Ross: You have no Heel pages left in your playbook!")
              )
          )
     )
    )
)

originalScripts.Special_Special:
(if ((eq #test 1)
     (and (not (WAIsStunned #this))
          (not (eq (WAGetValue (WAGameMap) NoSpecialAbilities)
                   1
               )
          )
          (lesser (count (WAGetHand #this)) 6)
          (greater-eq (WAGetTotalMomentum (WAGetOpponent #this)) 3)
     )
    )
    (True
     (block 
          (WADrawPage #this)
          True
     )
    )
)

originalScripts.Move_Connected:
(if ((eq #move #this)
     (WAMessage -1 "Jim Ross:" (WAGetName #superstar) "is really Stomping a Mudhole, and walking it dry!")
    )
)

originalScripts.Can_Be_Played:
(if ((eq #page #this)
     (if ((and (eq (WAGetBaseUNID #initiator) 2)
               (not (eq (WAGetValue (WAGameMap) PlayedTFS)
                        1
                    )
               )
               (not (eq (WAGetValue (WAGameMap) EventsPlayed)
                        3
                    )
               )
          )
          True
         )
         (True Nil)
     )
