     (block 
          (sett CanPlay (and (not (WAPlayedFanFavorite #initiator))
                             (not (eq #incontrol (WAGetOwner #this)))
                             (not (eq (WAGetValue (WAGameMap) EventsPlayed)
                                      3
                                  )
                             )
                             (not (eq (WAGetValue (WAGameMap) PlayedTheRattlesnake)
                                      1
                                  )
                             )
                             (greater-eq (WAGetValue #initiator Warnings) (add (WAGetValue #target Warnings) 4))
                        )
          )
          (enum (WAGetPlayers) Playa
                (if ((eq (WAGetBaseUNID (WAGetActiveSuperstar Playa))
                         2
                     )
                     (sett CanPlay Nil)
                    )
                )
          )
          CanPlay
     )
    )
    ((and (WAInPlay #this)
          (not (eq (WAGetOwner #page)
                   (WAGetOwner #this)
               )
          )
          (not (eq (WAGetValue #this Backfired) 1))
     )
     Nil
    )
    (True True)
)

